_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

_SYMBOLS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(number):
    """Roman numeral for an int from 1 to 3999."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    if not 1 <= number <= 3999:
        raise ValueError("number must be from 1 to 3999")
    parts = []
    for value, symbol in _VALUES:
        count, number = divmod(number, value)
        parts.append(symbol * count)
    return "".join(parts)


def from_roman(text):
    """The int for a standard Roman numeral."""
    if not isinstance(text, str) or not text:
        raise ValueError("not a Roman numeral: %r" % (text,))
    total = 0
    previous = 0
    for char in reversed(text):
        if char not in _SYMBOLS:
            raise ValueError("not a Roman numeral: %r" % (text,))
        value = _SYMBOLS[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    if not 1 <= total <= 3999:
        raise ValueError("not a Roman numeral: %r" % (text,))
    # Accept only the exact standard form that to_roman produces.
    if to_roman(total) != text:
        raise ValueError("not a standard Roman numeral: %r" % (text,))
    return total
